export interface BriefSection {
  readonly heading: string;
  readonly body: string;
  readonly bullets: readonly string[];
}

export interface OrganizationBrief {
  readonly title: string;
  readonly summary: string;
  readonly sections: readonly BriefSection[];
}

function escapeHtml(value: string): string {
  return value
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll("&", "&amp;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

export function renderOrganizationBrief(brief: OrganizationBrief): string {
  if (brief.title.length === 0 || brief.summary.length === 0) {
    throw new TypeError("Title and summary must be non-empty");
  }
  const sections = brief.sections.map((section) => {
    if (section.heading.length === 0 || section.body.length === 0 ||
        section.bullets.some((bullet) => bullet.length === 0)) {
      throw new TypeError("Section text must be non-empty");
    }
    const list = section.bullets.length === 0
      ? ""
      : `<ul>${section.bullets.map((bullet) => `<li>${escapeHtml(bullet)}</li>`).join("")}</ul>`;
    return `<section><h2>${escapeHtml(section.heading)}</h2><p>${escapeHtml(section.body)}</p>${list}</section>`;
  }).join("");
  return `<article><h1>${escapeHtml(brief.title)}</h1><p>${escapeHtml(brief.summary)}</p>${sections}</article>`;
}

