import { renderOrganizationBrief } from './solution';
import type { BriefSection, OrganizationBrief } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsTypeError(action: () => unknown, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  if (!(error instanceof TypeError)) throw new Error(message);
}

const emptySections: OrganizationBrief = {
  title: 'Acme',
  summary: 'A short summary',
  sections: [],
};
equal(
  renderOrganizationBrief(emptySections),
  '<article><h1>Acme</h1><p>A short summary</p></article>',
  'empty sections render only required tags',
);

const sections: BriefSection[] = [
  { heading: 'First & foremost', body: 'Use <carefully>.', bullets: [] },
  {
    heading: 'Quotes " and \'',
    body: 'Body & more',
    bullets: ['One < two', '"quoted" & \'apostrophe\'', 'last > first'],
  },
];
const brief: OrganizationBrief = {
  title: 'R&D <Group>',
  summary: 'Safe & "deterministic"',
  sections,
};
const html = renderOrganizationBrief(brief);
equal(
  html,
  '<article><h1>R&amp;D &lt;Group&gt;</h1><p>Safe &amp; &quot;deterministic&quot;</p><section><h2>First &amp; foremost</h2><p>Use &lt;carefully&gt;.</p></section><section><h2>Quotes &quot; and &#39;</h2><p>Body &amp; more</p><ul><li>One &lt; two</li><li>&quot;quoted&quot; &amp; &#39;apostrophe&#39;</li><li>last &gt; first</li></ul></section></article>',
  'exact compact HTML, escaping, and order',
);
equal(sections.length, 2, 'section input not mutated');
equal(sections[1].bullets[0], 'One < two', 'bullet input not mutated');

throwsTypeError(() => renderOrganizationBrief({ title: '', summary: 'x', sections: [] }), 'empty title rejected');
throwsTypeError(() => renderOrganizationBrief({ title: 'x', summary: '', sections: [] }), 'empty summary rejected');
throwsTypeError(
  () => renderOrganizationBrief({ title: 'x', summary: 'y', sections: [{ heading: '', body: 'b', bullets: [] }] }),
  'empty heading rejected',
);
throwsTypeError(
  () => renderOrganizationBrief({ title: 'x', summary: 'y', sections: [{ heading: 'h', body: '', bullets: [] }] }),
  'empty body rejected',
);
throwsTypeError(
  () => renderOrganizationBrief({ title: 'x', summary: 'y', sections: [{ heading: 'h', body: 'b', bullets: ['ok', ''] }] }),
  'empty bullet rejected',
);

